// —— 目标：挖木头 → 做工作台、木棍 → 升级石质工具 ——
try {
  const logNames = ['oak_log','birch_log','spruce_log','jungle_log','acacia_log','dark_oak_log']

  // 1. 找树并挖木头
  let dug = 0
  for (let i = 0; i < 12; i++) {
    let t = await actions.findAny(logNames, 48)
    if (!t) {
      // 附近没树就四处走走再找
      await actions.wander(4)
      await sleep(300)
      t = await actions.findAny(logNames, 48)
      if (!t) break
    }
    const ok = await actions.digAt(t)
    if (!ok) break          // 够不到/挖不动就收手，避免死循环
    dug++
    await sleep(150)
  }

  // 2. 看看挖到了哪种木头
  let logType = null, logCount = 0
  for (const n of logNames) {
    const c = actions.countOf(n)
    if (c > 0) { logType = n; logCount = c; break }
  }
  if (!logType) {
    return '没挖到木头（挖了' + dug + '个方块），先回去别硬凑'
  }

  // 3. 原木 → 木板
  const plankType = logType.replace('_log', '_planks')
  try { await actions.craft(plankType, logCount * 4) } catch (e) { log('做木板出错:' + e) }
  const planks = actions.countOf(plankType)

  // 4. 做工作台并放到脚边
  if (planks >= 4 && !actions.item('crafting_table')) {
    try { await actions.craft('crafting_table', 1) } catch (e) { log('做工作台出错:' + e) }
  }
  if (actions.item('crafting_table')) {
    try { await actions.placeNearby('crafting_table') } catch (e) { log('放工作台出错:' + e) }
  }

  // 5. 做木棍（工具要用）
  if (actions.countOf(plankType) >= 2 && actions.countOf('stick') < 4) {
    try { await actions.craft('stick', 8) } catch (e) { log('做木棍出错:' + e) }
  }

  // 6. 升级石质工具（背包里有 216 个圆石，够用）
  const stoneCount = actions.countOf('cobblestone')
  const stickCount = actions.countOf('stick')
  const made = []

  if (stoneCount >= 3 && stickCount >= 2 && !actions.item('stone_pickaxe')) {
    try { await actions.craft('stone_pickaxe', 1); made.push('石镐') } catch (e) { log('做石镐出错:' + e) }
  }
  if (stoneCount >= 3 && stickCount >= 2 && !actions.item('stone_axe')) {
    try { await actions.craft('stone_axe', 1); made.push('石斧') } catch (e) { log('做石斧出错:' + e) }
  }
  if (stoneCount >= 2 && stickCount >= 1 && !actions.item('stone_sword')) {
    try { await actions.craft('stone_sword', 1); made.push('石剑') } catch (e) { log('做石剑出错:' + e) }
  }

  // 7. 换上石镐
  if (actions.item('stone_pickaxe')) {
    try { await actions.equip('stone_pickaxe') } catch (e) { log('装备石镐出错:' + e) }
  }

  return '挖了' + dug + '段' + logType + '，做了' + actions.countOf(plankType) + '木板、' +
         actions.countOf('stick') + '木棍，工作台：' + (actions.item('crafting_table') ? '有' : '无') +
         '，新工具：' + (made.length ? made.join('、') : '无')
} catch (e) {
  return '出错了: ' + e
}

// 目标：把脚边的铜矿石捡起来/挖出来，堆成一摞看看能摞多高
try {
  // 1. 先看看背包里现在有多少铜矿石相关物品
  let have = actions.countOf('raw_copper') + actions.countOf('copper_ore')
  log('开始时铜相关物品：' + have)

  // 2. 看看附近有没有铜矿石方块（脚边、周围）
  let mined = 0
  for (let i = 0; i < 40; i++) {
    const ore = await actions.findBlock('copper_ore', 8)
    if (!ore) break

    // 换到合适的镐，石镐以上才能挖铜矿
    try { await actions.bestToolFor(ore) } catch (e) { log('换工具出错:' + e) }

    const ok = await actions.digAt(ore)
    if (!ok) {
      // 够不到就挪近点再试一次
      try { await actions.goto(ore.x, ore.y, ore.z, 2) } catch (e) {}
      const ok2 = await actions.digAt(ore)
      if (!ok2) break
    }
    mined++
    await sleep(120)
  }

  // 3. 把地上的掉落物捡起来
  for (let i = 0; i < 5; i++) {
    try { await actions.pickupNearby(4) } catch (e) { log('捡东西出错:' + e) }
    await sleep(200)
  }

  // 4. 数一数现在有多少铜矿石
  const copperOre = actions.countOf('copper_ore')
  const rawCopper = actions.countOf('raw_copper')
  let total = copperOre + rawCopper

  // 5. 如果挖到的是 raw_copper，先熔炼？没有炉子的话就先算 raw_copper 摞起来
  //    这里直接统计能摞起来的总数（铜矿石方块 / 原铜）
  let stackCount = total
  let height = Math.floor(stackCount / 1) // 每格摞1个方块高度计算
  // 如果要做成铜锭也能摞，但我们先按现有物品摞

  // 6. 尝试垒起来：有铜矿石方块就垒方块，否则把 raw_copper 摞在脚边（用 place 放不了 raw_copper，只能放方块）
  let placed = 0
  if (copperOre > 0) {
    // 选个脚边空地垒
    for (let i = 0; i < copperOre && i < 17; i++) {
      const p = actions.pos()
      const ok = await actions.place('copper_ore', p.x + 1, p.y + (placed < 16 ? placed : 0), p.z)
      if (ok) placed++
      // 摞满了就换个位置
      if (placed >= 16) break
      await sleep(100)
    }
  }

  const finalCopperOre = actions.countOf('copper_ore')
  const finalRaw = actions.countOf('raw_copper')

  return '挖了' + mined + '个铜矿方块，现在有铜矿石' + finalCopperOre + '个、原铜' + finalRaw +
         '个，一共' + (finalCopperOre + finalRaw) + '个铜料，垒起了' + placed + '块铜矿石'
} catch (e) {
  return '出错了: ' + e
}

// 目标：用石镐在附近挖石头，看看能不能挖到铁或煤
try {
  const beforeIron = actions.countOf('raw_iron')
  const beforeCoal = actions.countOf('coal')

  // —— 1. 确保有石镐（挖铁矿必须要石镐以上）——
  if (!actions.item('stone_pickaxe')) {
    // 没木棍就找棵树做
    if (actions.countOf('stick') < 2) {
      const logNames = ['oak_log', 'birch_log', 'spruce_log']
      let t = null
      for (let i = 0; i < 5 && !t; i++) {
        try { t = await actions.findAny(logNames, 40) } catch (e) { log('找树出错:' + e) }
        if (!t) { await actions.wander(5); await sleep(300) }
      }
      if (t) {
        try { await actions.digAt(t) } catch (e) { log('砍树出错:' + e) }
        await sleep(200)
        let logType = null
        for (const n of logNames) { if (actions.countOf(n) > 0) { logType = n; break } }
        if (logType) {
          const plankType = logType.replace('_log', '_planks')
          try { await actions.craft(plankType, 4) } catch (e) { log('做木板出错:' + e) }
          try { await actions.craft('stick', 4) } catch (e) { log('做木棍出错:' + e) }
        }
      }
    }
    // 有材料就做石镐
    if (actions.countOf('cobblestone') >= 3 && actions.countOf('stick') >= 2) {
      try { await actions.craft('stone_pickaxe', 1) } catch (e) { log('做石镐出错:' + e) }
    }
  }
  // 手持石镐
  const toolOK = !!actions.item('stone_pickaxe')
  if (toolOK) {
    try { await actions.equip('stone_pickaxe') } catch (e) { log('装备石镐出错:' + e) }
  }

  // —— 2. 找矿挖矿：有石镐才挖铁矿，否则只挖煤 ——
  const oreNames = toolOK
    ? ['coal_ore', 'iron_ore', 'deepslate_coal_ore', 'deepslate_iron_ore']
    : ['coal_ore', 'deepslate_coal_ore']

  let minedOre = 0
  let minedRock = 0
  for (let i = 0; i < 24; i++) {
    let isOre = true
    let target = null
    try { target = await actions.findAny(oreNames, 20) } catch (e) { log('找矿出错:' + e) }
    if (!target) {
      // 附近没矿就挖点石头碰运气
      isOre = false
      try { target = await actions.findBlock('stone', 16) } catch (e) { log('找石头出错:' + e) }
      if (!target) {
        try { target = await actions.findBlock('andesite', 16) } catch (e) {}
      }
      if (!target) break
    }

    try { await actions.bestToolFor(target) } catch (e) { log('换工具出错:' + e) }

    let ok = false
    try { ok = await actions.digAt(target) } catch (e) { log('挖出错:' + e) }
    if (!ok) {
      // 够不到就靠近再试一次
      try { await actions.goto(target.x, target.y, target.z, 2) } catch (e) {}
      try { ok = await actions.digAt(target) } catch (e) {}
    }
    if (!ok) {
      // 实在挖不动就换个地方，别卡死
      await actions.wander(3)
      await sleep(250)
      continue
    }
    if (isOre) minedOre++
    else minedRock++
    await sleep(140)
  }

  // —— 3. 捡地上的掉落物 ——
  for (let i = 0; i < 4; i++) {
    try { await actions.pickupNearby(5) } catch (e) { log('捡东西出错:' + e) }
    await sleep(200)
  }

  // —— 4. 统计成果 ——
  const iron = actions.countOf('raw_iron') - beforeIron
  const coal = actions.countOf('coal') - beforeCoal
  const part = []
  if (iron > 0) part.push('铁' + iron + '个')
  if (coal > 0) part.push('煤' + coal + '个')
  const gain = part.length ? '挖到 ' + part.join('、') : '没挖到铁和煤'

  return '用' + (toolOK ? '石镐' : '木镐(没做出石镐,铁矿挖不了)') +
         '挖了' + minedOre + '个矿、' + minedRock + '块石头，' + gain +
         '；现在背包石头/cobblestone ' + actions.countOf('cobblestone') + ' 个'
} catch (e) {
  return '出错了: ' + e
}

// 目标：往上挖几格，摸摸头顶那片青金石矿脉有多大
try {
  // 1. 先看看背包里现有的青金石，记下初始值
  const beforeLapis = actions.countOf('lapis_lazuli')
  const beforeOre = actions.countOf('lapis_ore') + actions.countOf('deepslate_lapis_ore')

  // 2. 找石镐（挖青金石需要石镐以上），没有就现场做一个
  if (!actions.item('stone_pickaxe')) {
    if (actions.countOf('cobblestone') >= 3 && actions.countOf('stick') >= 2) {
      try { await actions.craft('stone_pickaxe', 1) } catch (e) { log('做石镐出错:' + e) }
    }
  }
  if (!actions.item('stone_pickaxe')) {
    // 实在没镐，至少用现有的木镐/石镐顶上
    if (actions.item('wooden_pickaxe')) {
      try { await actions.equip('wooden_pickaxe') } catch (e) {}
    }
  } else {
    try { await actions.equip('stone_pickaxe') } catch (e) { log('装备石镐出错:' + e) }
  }

  // 3. 在地形里找青金石矿（含深板岩版），只找头顶附近的
  const lapisNames = ['lapis_ore', 'deepslate_lapis_ore']
  let minedOre = 0
  let tried = 0

  // 反复找最近的青金石矿去挖，直到找不到或挖够次数
  for (let i = 0; i < 16; i++) {
    tried++
    let target = null
    try { target = await actions.findAny(lapisNames, 12) } catch (e) { log('找矿出错:' + e) }

    if (!target) {
      // 附近没有就往上挖一格碰运气：先看头顶方块
      const p = actions.pos()
      let upBlock = null
      try { upBlock = await actions.blockAt(p.x, p.y + 2, p.z) } catch (e) {}
      if (upBlock && upBlock.name && upBlock.name !== 'air') {
        // 头顶那格挖掉
        try { await actions.digAt(upBlock) } catch (e) { log('挖头顶出错:' + e) }
        await sleep(150)
        // 往上走一格（跳上去）
        try { await actions.walkToward(0, 0, 400) } catch (e) {}
        try { await actions.goto(p.x, p.y + 1, p.z, 0) } catch (e) {}
        await sleep(150)
        continue
      }
      // 上面是空的？那就真的没矿了，换着走几步再找
      await actions.wander(3)
      await sleep(200)
      continue
    }

    // 换到最合适的镐
    try { await actions.bestToolFor(target) } catch (e) { log('换工具出错:' + e) }

    let ok = false
    try { ok = await actions.digAt(target) } catch (e) { log('挖矿出错:' + e) }
    if (!ok) {
      // 够不到，靠近一点再试
      try { await actions.goto(target.x, target.y, target.z, 1) } catch (e) {}
      try { ok = await actions.digAt(target) } catch (e) {}
    }
    if (ok) {
      minedOre++
    } else {
      // 挖不动就换地方
      await actions.wander(2)
      await sleep(200)
    }
    await sleep(130)
  }

  // 4. 捡地上的掉落物
  for (let i = 0; i < 4; i++) {
    try { await actions.pickupNearby(5) } catch (e) { log('捡东西出错:' + e) }
    await sleep(180)
  }

  // 5. 统计成果
  const nowLapis = actions.countOf('lapis_lazuli')
  const nowOre = actions.countOf('lapis_ore') + actions.countOf('deepslate_lapis_ore')
  const gainLapis = nowLapis - beforeLapis
  const gainOre = nowOre - beforeOre

  return '往上摸了一圈，挖了' + minedOre + '块青金石矿（尝试' + tried + '轮），' +
         '青金石' + (gainLapis > 0 ? '+' + gainLapis : '没变') +
         '，矿石块' + (gainOre > 0 ? '+' + gainOre : '没变') +
         '；现在背包青金石共' + nowLapis + '个'
} catch (e) {
  return '出错了: ' + e
}

// 目标：用石镐挖身边的石头和泥土，在脚边围两格高的封闭临时避难所过夜
try {
  const logNames = ['oak_log', 'birch_log', 'spruce_log']

  // —— 1. 确保有镐子和剑，先换石镐 ——
  if (actions.item('stone_pickaxe')) {
    try { await actions.equip('stone_pickaxe') } catch (e) {}
  } else if (actions.item('wooden_pickaxe')) {
    try { await actions.equip('wooden_pickaxe') } catch (e) {}
  }

  // —— 2. 挖一点身边的石头/泥土备料（作为方块用）——
  const stoneNames = ['stone', 'andesite', 'diorite', 'granite', 'cobblestone', 'dirt']
  let mined = 0
  for (let i = 0; i < 20; i++) {
    let target = null
    try { target = await actions.findAny(stoneNames, 6) } catch (e) {}
    if (!target) break
    try { await actions.bestToolFor(target) } catch (e) {}
    let ok = false
    try { ok = await actions.digAt(target) } catch (e) {}
    if (!ok) {
      try { await actions.goto(target.x, target.y, target.z, 2) } catch (e) {}
      try { ok = await actions.digAt(target) } catch (e) {}
    }
    if (!ok) break
    mined++
    await sleep(120)
  }
  // 捡地上的掉落物
  for (let i = 0; i < 3; i++) {
    try { await actions.pickupNearby(4) } catch (e) {}
    await sleep(150)
  }

  // —— 3. 选一种建墙方块 ——
  let blockType = null
  for (const n of ['cobblestone', 'stone', 'dirt', 'andesite', 'diorite', 'granite']) {
    if (actions.countOf(n) >= 12) { blockType = n; break }
  }
  if (!blockType) {
    // 料不够就再补挖
    for (let i = 0; i < 15; i++) {
      let t = null
      try { t = await actions.findAny(['dirt', 'stone'], 6) } catch (e) {}
      if (!t) break
      try { await actions.digAt(t) } catch (e) { break }
      await sleep(100)
    }
    try { await actions.pickupNearby(4) } catch (e) {}
    for (const n of ['cobblestone', 'stone', 'dirt', 'andesite', 'diorite', 'granite']) {
      if (actions.countOf(n) >= 8) { blockType = n; break }
    }
  }
  if (!blockType) {
    return '石头/泥土不够，没法搭避难所，先回去了'
  }

  // —— 4. 确认脚下位置，把脚边地面挖平（找站立位置）——
  const p0 = actions.pos()
  const bx = p0.x, by = p0.y, bz = p0.z
  // 确保头顶两格空出来（别被卡住）
  try {
    const above1 = await actions.blockAt(bx, by + 1, bz)
    if (above1 && above1 !== 'air' && above1 !== 'cave_air') {
      const b = await actions.blockAt(bx, by + 1, bz)
      try { await actions.digAt({ x: bx, y: by + 1, z: bz, name: b }) } catch (e) {}
    }
  } catch (e) {}

  // —— 5. 在脚下这块 3x3 区域围一圈两格高的墙（中间1格留给自己站）——
  // 站的圆心 = (bx, by, bz)，周围8格墙，高度 by+1 和 by+2 各一层
  let placed = 0
  let fail = 0
  const ring = []
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      if (dx === 0 && dz === 0) continue // 中间是自己
      ring.push([dx, dz])
    }
  }
  // 先围低层，再围高层
  for (const level of [1, 2]) {
    for (const [dx, dz] of ring) {
      const x = bx + dx, y = by + level, z = bz + dz
      let cur = null
      try { cur = await actions.blockAt(x, y, z) } catch (e) {}
      // 已经是实心方块就不用放了
      if (cur && cur !== 'air' && cur !== 'cave_air' && cur !== 'water') { continue }
      let ok = false
      try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
      if (ok) placed++
      else {
        fail++
        // 失败一次就换到附近方块再试（可能太远）
        try { await actions.goto(x, by, z, 2) } catch (e) {}
        try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
        if (ok) { placed++; fail-- }
      }
      await sleep(80)
      if (fail > 8) break
    }
    if (fail > 8) break
  }

  // —— 6. 封顶：在头顶 by+3 铺一层，把自己盖住 ——
  let roofPlaced = 0
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      const x = bx + dx, y = by + 3, z = bz + dz
      let cur = null
      try { cur = await actions.blockAt(x, y, z) } catch (e) {}
      if (cur && cur !== 'air' && cur !== 'cave_air') continue
      let ok = false
      try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
      if (!ok) {
        try { await actions.goto(x, by + 1, z, 2) } catch (e) {}
        try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
      }
      if (ok) roofPlaced++
      await sleep(80)
    }
  }

  // —— 7. 回到中心站好，检查封闭情况 ——
  try { await actions.goto(bx, by, bz, 1) } catch (e) {}
  await sleep(300)

  // 检查四周是否都封上了
  let sealed = 0
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      if (dx === 0 && dz === 0) continue
      const b = await actions.blockAt(bx + dx, by + 1, bz + dz)
      if (b && b !== 'air' && b !== 'cave_air') sealed++
    }
  }

  return '挖了' + mined + '块石头/泥土，用' + blockType + '围了避难所：墙' + placed +
         '块、顶' + roofPlaced + '块，四周封闭' + sealed + '/8，现在在(' +
         bx + ',' + by + ',' + bz + ')准备过夜'
} catch (e) {
  return '出错了: ' + e
}

// —— 目标：石斧砍木头 → 做工作台、木棍 → 升级石质工具 ——
try {
  const logNames = ['oak_log', 'birch_log', 'spruce_log', 'jungle_log', 'acacia_log', 'dark_oak_log']

  // 1. 拿石斧，准备砍树
  if (actions.item('stone_axe')) {
    try { await actions.equip('stone_axe') } catch (e) { log('装备石斧出错:' + e) }
  } else if (actions.item('wooden_axe')) {
    try { await actions.equip('wooden_axe') } catch (e) { log('装备木斧出错:' + e) }
  }

  // 2. 找树挖木头
  let dug = 0
  for (let i = 0; i < 10; i++) {
    let t = null
    try { t = await actions.findAny(logNames, 48) } catch (e) { log('找树出错:' + e) }
    if (!t) {
      await actions.wander(5)
      await sleep(300)
      try { t = await actions.findAny(logNames, 48) } catch (e) {}
      if (!t) break
    }
    if (actions.item('stone_axe')) { try { await actions.equip('stone_axe') } catch (e) {} }
    let ok = false
    try { ok = await actions.digAt(t) } catch (e) { log('挖树出错:' + e) }
    if (!ok) {
      // 够不到就靠近再试一次
      try { await actions.goto(t.x, t.y, t.z, 2) } catch (e) {}
      try { ok = await actions.digAt(t) } catch (e) {}
    }
    if (!ok) break
    dug++
    await sleep(150)
  }

  // 捡一下地上的木头
  for (let i = 0; i < 3; i++) {
    try { await actions.pickupNearby(4) } catch (e) {}
    await sleep(150)
  }

  // 3. 统计木头
  let logType = null, logCount = 0
  for (const n of logNames) {
    const c = actions.countOf(n)
    if (c > 0) { logType = n; logCount = c; break }
  }
  if (!logType) {
    return '没挖到木头（挖了' + dug + '个方块），先收手'
  }

  // 4. 原木 → 木板
  const plankType = logType.replace('_log', '_planks')
  try { await actions.craft(plankType, logCount * 4) } catch (e) { log('做木板出错:' + e) }
  const planks = actions.countOf(plankType)

  // 5. 做工作台
  if (planks >= 4 && !actions.item('crafting_table')) {
    try { await actions.craft('crafting_table', 1) } catch (e) { log('做工作台出错:' + e) }
  }
  if (actions.item('crafting_table')) {
    try { await actions.placeNearby('crafting_table') } catch (e) { log('放工作台出错:' + e) }
  }

  // 6. 做木棍
  if (actions.countOf(plankType) >= 2 && actions.countOf('stick') < 4) {
    try { await actions.craft('stick', 8) } catch (e) { log('做木棍出错:' + e) }
  }

  // 7. 升级石质工具（背包里已有圆石和石剑石斧，补齐石镐）
  const made = []
  const stoneCount = () => actions.countOf('cobblestone')
  const stickCount = () => actions.countOf('stick')

  if (stoneCount() >= 3 && stickCount() >= 2 && !actions.item('stone_pickaxe')) {
    try { await actions.craft('stone_pickaxe', 1); made.push('石镐') } catch (e) { log('做石镐出错:' + e) }
  }
  if (stoneCount() >= 3 && stickCount() >= 2 && !actions.item('stone_axe')) {
    try { await actions.craft('stone_axe', 1); made.push('石斧') } catch (e) { log('做石斧出错:' + e) }
  }
  if (stoneCount() >= 2 && stickCount() >= 1 && !actions.item('stone_sword')) {
    try { await actions.craft('stone_sword', 1); made.push('石剑') } catch (e) { log('做石剑出错:' + e) }
  }

  // 8. 换上石镐
  if (actions.item('stone_pickaxe')) {
    try { await actions.equip('stone_pickaxe') } catch (e) { log('装备石镐出错:' + e) }
  }

  return '砍了' + dug + '段' + logType + '，做了' + actions.countOf(plankType) + '木板、' +
         actions.countOf('stick') + '木棍，工作台：' + (actions.item('crafting_table') ? '有' : '无') +
         '，新工具：' + (made.length ? made.join('、') : '无')
} catch (e) {
  return '出错了: ' + e
}

// 目标：在脚边围一个两格高的封闭临时避难所，安全过夜
try {
  await actions.ensureChunks()

  const p = actions.pos()
  const bx = p.x, by = p.y, bz = p.z
  log('当前站在 (' + bx + ',' + by + ',' + bz + ')，时间晚上')

  // —— 1. 尝试挖点身边的泥土/石头（有镐就挖石头，没有就用手/斧挖泥土）——
  let mined = 0
  try {
    const hasPick = actions.item('stone_pickaxe') || actions.item('wooden_pickaxe') ||
                    actions.item('iron_pickaxe') || actions.item('diamond_pickaxe')
    const names = hasPick
      ? ['stone', 'andesite', 'diorite', 'dirt']
      : ['dirt']
    for (let i = 0; i < 4; i++) {
      let t = null
      try { t = await actions.findAny(names, 3) } catch (e) {}
      if (!t) break
      // 别挖自己脚下或正上方的支撑块
      if (t.x === bx && t.z === bz && (t.y === by || t.y === by - 1)) break
      try { await actions.bestToolFor(t) } catch (e) {}
      let ok = false
      try { ok = await actions.digAt(t) } catch (e) {}
      if (!ok) break
      mined++
      await sleep(100)
    }
    try { await actions.pickupNearby(3) } catch (e) {}
  } catch (e) {}

  // —— 2. 清空头顶，保证不被卡住 ——
  for (const dy of [1, 2]) {
    try {
      const b = await actions.blockAt(bx, by + dy, bz)
      if (b && b !== 'air' && b !== 'cave_air') {
        try { await actions.digAt({ x: bx, y: by + dy, z: bz, name: b }) } catch (e) {}
      }
    } catch (e) {}
  }
  await sleep(150)

  // —— 3. 选一种建墙方块（背包里石头/泥土很多，直接用）——
  let blockType = null
  for (const n of ['cobblestone', 'dirt', 'andesite', 'stone', 'diorite', 'stone_bricks']) {
    if (actions.countOf(n) >= 14) { blockType = n; break }
  }
  if (!blockType) return '身上没有足够的方块搭避难所，只能先躲一躲'

  // —— 4. 在脚边围 3x3 的两格高墙（脚边 y 和头顶 y+1），中间留给自己 ——
  const ring = []
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      if (dx === 0 && dz === 0) continue
      ring.push([dx, dz])
    }
  }

  let placed = 0
  for (const dy of [0, 1]) {
    for (const [dx, dz] of ring) {
      const x = bx + dx, y = by + dy, z = bz + dz
      let cur = null
      try { cur = await actions.blockAt(x, y, z) } catch (e) {}
      if (cur && cur !== 'air' && cur !== 'cave_air' && cur !== 'water') continue // 已是实心
      let ok = false
      try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
      if (!ok) {
        // 站回中心再试一次（可能距离太远）
        try { await actions.goto(bx, by, bz, 1) } catch (e) {}
        try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
      }
      if (ok) placed++
      await sleep(70)
    }
  }

  // —— 5. 封顶：头顶 by+2 铺一层 3x3 ——
  let roof = 0
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      const x = bx + dx, y = by + 2, z = bz + dz
      let cur = null
      try { cur = await actions.blockAt(x, y, z) } catch (e) {}
      if (cur && cur !== 'air' && cur !== 'cave_air') continue
      let ok = false
      try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
      if (!ok) {
        try { await actions.goto(bx, by, bz, 1) } catch (e) {}
        try { ok = await actions.place(blockType, x, y, z) } catch (e) {}
      }
      if (ok) roof++
      await sleep(70)
    }
  }

  // —— 6. 回到中心站好，检查封闭情况 ——
  try { await actions.goto(bx, by, bz, 1) } catch (e) {}
  await sleep(300)

  let sealedWalls = 0
  for (const dy of [0, 1]) {
    for (const [dx, dz] of ring) {
      try {
        const b = await actions.blockAt(bx + dx, by + dy, bz + dz)
        if (b && b !== 'air' && b !== 'cave_air') sealedWalls++
      } catch (e) {}
    }
  }
  let sealedRoof = 0
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      try {
        const b = await actions.blockAt(bx + dx, by + 2, bz + dz)
        if (b && b !== 'air' && b !== 'cave_air') sealedRoof++
      } catch (e) {}
    }
  }

  return '在(' + bx + ',' + by + ',' + bz + ')用' + blockType + '搭了2格高避难所：' +
         '挖料' + mined + '块，砌墙' + placed + '块、封顶' + roof + '块；' +
         '封闭墙' + sealedWalls + '/16、顶' + sealedRoof + '/9，可以过夜了'
} catch (e) {
  return '出错了: ' + e
}

// 目标：用石镐在附近挖石头，看看能不能挖到铁或煤
try {
  const beforeIron = actions.countOf('raw_iron')
  const beforeCoal = actions.countOf('coal')

  // —— 1. 确保有石镐 ——
  if (!actions.item('stone_pickaxe')) {
    // 没木棍就砍树做
    if (actions.countOf('stick') < 2) {
      const logNames = ['oak_log', 'birch_log', 'spruce_log']
      let t = null
      for (let i = 0; i < 5 && !t; i++) {
        try { t = await actions.findAny(logNames, 48) } catch (e) { log('找树出错:' + e) }
        if (!t) { await actions.wander(5); await sleep(300) }
      }
      if (t) {
        try { await actions.equip('stone_axe') } catch (e) {}
        try { await actions.digAt(t) } catch (e) { log('砍树出错:' + e) }
        await sleep(200)
        try { await actions.pickupNearby(4) } catch (e) {}
        let logType = null
        for (const n of logNames) { if (actions.countOf(n) > 0) { logType = n; break } }
        if (logType) {
          const plankType = logType.replace('_log', '_planks')
          try { await actions.craft(plankType, 4) } catch (e) { log('做木板出错:' + e) }
          try { await actions.craft('stick', 4) } catch (e) { log('做木棍出错:' + e) }
        }
      }
    }
    // 材料够就做石镐
    if (actions.countOf('cobblestone') >= 3 && actions.countOf('stick') >= 2) {
      try { await actions.craft('stone_pickaxe', 1) } catch (e) { log('做石镐出错:' + e) }
    }
  }
  const toolOK = !!actions.item('stone_pickaxe')
  if (toolOK) {
    try { await actions.equip('stone_pickaxe') } catch (e) { log('装备石镐出错:' + e) }
  } else {
    return '做不出石镐，挖不了矿，先收手'
  }

  // —— 2. 找矿挖矿 ——
  const oreNames = ['coal_ore', 'iron_ore', 'deepslate_coal_ore', 'deepslate_iron_ore']
  let minedOre = 0
  let minedRock = 0
  for (let i = 0; i < 24; i++) {
    let isOre = true
    let target = null
    try { target = await actions.findAny(oreNames, 20) } catch (e) { log('找矿出错:' + e) }
    if (!target) {
      // 附近没矿就挖点石头碰运气
      isOre = false
      try { target = await actions.findBlock('stone', 12) } catch (e) { log('找石头出错:' + e) }
      if (!target) { try { target = await actions.findBlock('andesite', 12) } catch (e) {} }
      if (!target) { try { target = await actions.findBlock('diorite', 12) } catch (e) {} }
      if (!target) break
    }

    try { await actions.bestToolFor(target) } catch (e) { log('换工具出错:' + e) }

    let ok = false
    try { ok = await actions.digAt(target) } catch (e) { log('挖出错:' + e) }
    if (!ok) {
      // 够不到就靠近再试一次
      try { await actions.goto(target.x, target.y, target.z, 2) } catch (e) {}
      try { ok = await actions.digAt(target) } catch (e) {}
    }
    if (!ok) {
      // 挖不动就换地方，别卡死
      await actions.wander(3)
      await sleep(250)
      continue
    }
    if (isOre) minedOre++
    else minedRock++
    await sleep(140)
  }

  // —— 3. 捡掉落物 ——
  for (let i = 0; i < 4; i++) {
    try { await actions.pickupNearby(5) } catch (e) { log('捡东西出错:' + e) }
    await sleep(200)
  }

  // —— 4. 统计成果 ——
  const iron = actions.countOf('raw_iron') - beforeIron
  const coal = actions.countOf('coal') - beforeCoal
  const part = []
  if (iron > 0) part.push('铁' + iron + '个')
  if (coal > 0) part.push('煤' + coal + '个')
  const gain = part.length ? '挖到 ' + part.join('、') : '没挖到铁和煤'

  return '用石镐挖了' + minedOre + '个矿、' + minedRock + '块石头，' + gain +
         '；背包圆石 ' + actions.countOf('cobblestone') + ' 个'
} catch (e) {
  return '出错了: ' + e
}

// 目标：用石斧砍树凑木头 → 做工作台、木棍 → 补齐石质工具（石镐）
try {
  const logNames = ['oak_log','birch_log','spruce_log','jungle_log','acacia_log','dark_oak_log']

  // 1. 手持石斧（砍树快）
  if (actions.item('stone_axe')) {
    try { await actions.equip('stone_axe') } catch (e) { log('装备石斧出错:' + e) }
  }

  // 2. 找树挖木头
  let dug = 0
  for (let i = 0; i < 12; i++) {
    let t = null
    try { t = await actions.findAny(logNames, 48) } catch (e) { log('找树出错:' + e) }
    if (!t) {
      await actions.wander(5)
      await sleep(300)
      try { t = await actions.findAny(logNames, 48) } catch (e) {}
      if (!t) break
    }
    if (actions.item('stone_axe')) { try { await actions.equip('stone_axe') } catch (e) {} }
    let ok = false
    try { ok = await actions.digAt(t) } catch (e) { log('挖树出错:' + e) }
    if (!ok) {
      // 够不到就靠近再试一次
      try { await actions.goto(t.x, t.y, t.z, 2) } catch (e) {}
      try { ok = await actions.digAt(t) } catch (e) {}
    }
    if (!ok) break
    dug++
    await sleep(150)
  }

  // 3. 捡地上的木头
  for (let i = 0; i < 3; i++) {
    try { await actions.pickupNearby(4) } catch (e) {}
    await sleep(150)
  }

  // 4. 统计木头
  let logType = null, logCount = 0
  for (const n of logNames) {
    const c = actions.countOf(n)
    if (c > 0) { logType = n; logCount = c; break }
  }
  if (!logType) {
    return '没挖到木头（挖了' + dug + '个方块），先收手'
  }

  // 5. 原木 → 木板
  const plankType = logType.replace('_log', '_planks')
  try { await actions.craft(plankType, logCount * 4) } catch (e) { log('做木板出错:' + e) }

  // 6. 做工作台并放下
  if (actions.countOf(plankType) >= 4 && !actions.item('crafting_table')) {
    try { await actions.craft('crafting_table', 1) } catch (e) { log('做工作台出错:' + e) }
  }
  if (actions.item('crafting_table')) {
    try { await actions.placeNearby('crafting_table') } catch (e) { log('放工作台出错:' + e) }
  }

  // 7. 做木棍（工具要用）
  if (actions.countOf(plankType) >= 2 && actions.countOf('stick') < 4) {
    try { await actions.craft('stick', 8) } catch (e) { log('做木棍出错:' + e) }
  }

  // 8. 补齐石质工具（背包里有 218 个圆石，够用）
  const made = []
  const stone = () => actions.countOf('cobblestone')
  const stick = () => actions.countOf('stick')

  if (stone() >= 3 && stick() >= 2 && !actions.item('stone_pickaxe')) {
    try { await actions.craft('stone_pickaxe', 1); made.push('石镐') } catch (e) { log('做石镐出错:' + e) }
  }
  if (stone() >= 3 && stick() >= 2 && !actions.item('stone_axe')) {
    try { await actions.craft('stone_axe', 1); made.push('石斧') } catch (e) { log('做石斧出错:' + e) }
  }
  if (stone() >= 2 && stick() >= 1 && !actions.item('stone_sword')) {
    try { await actions.craft('stone_sword', 1); made.push('石剑') } catch (e) { log('做石剑出错:' + e) }
  }
  if (stone() >= 3 && stick() >= 2 && !actions.item('stone_hoe')) {
    try { await actions.craft('stone_hoe', 1); made.push('石锄') } catch (e) { log('做石锄出错:' + e) }
  }
  if (stone() >= 3 && stick() >= 2 && !actions.item('stone_shovel')) {
    try { await actions.craft('stone_shovel', 1); made.push('石铲') } catch (e) { log('做石铲出错:' + e) }
  }

  // 9. 换上石镐（挖矿用）
  if (actions.item('stone_pickaxe')) {
    try { await actions.equip('stone_pickaxe') } catch (e) { log('装备石镐出错:' + e) }
  }

  return '砍了' + dug + '段' + logType + '，做了' + actions.countOf(plankType) + '木板、' +
         actions.countOf('stick') + '木棍，工作台：' + (actions.item('crafting_table') ? '有' : '无') +
         '，新工具：' + (made.length ? made.join('、') : '无') +
         '，石镐：' + (actions.item('stone_pickaxe') ? '有' : '无')
} catch (e) {
  return '出错了: ' + e
}
